    async function save(event, request) {
        if (saving) return false;
        for (const input of request?.skipInputs ? [] : root.querySelectorAll('input,select,textarea')) {
            if (!input.checkValidity()) {
                window.offerweave_OfferWorkspace.open(input);
                openSettings(input);
                input.reportValidity();
                return false;
            }
        }
        const button = root.querySelector('[data-save]');
        saving = true;
        button.disabled = true;
        button.textContent = __('Saving …', 'offerweave');
        try {
            const result = await api(request?.route || 'admin/config', request?.data || config);
            config = result.config;
            validationIssues = [];
            dirty = false;
            message = __('Configuration saved. New price previews now use this revision.', 'offerweave');
            error = false;
            render();
            return true;
        } catch (e) {
            message = e.message;
            error = true;
            validationIssues = e.issues || [];
            paintValidation();
            root.querySelector('.qb-message').scrollIntoView({ block: 'nearest' });
            button.disabled = false;
            button.textContent = __('Save changes', 'offerweave');
            return false;
        } finally {
            saving = false;
        }
    }
    function issueControl(issue) {
        if (issue.tab === 'offers' && (tab !== 'offers' || config.offers[selected]?.id !== issue.offer_id))
            return null;
        return [...root.querySelectorAll('[data-bind]')]
            .filter(
                (input) =>
                    issue.path === input.dataset.bind || issue.path.startsWith(input.dataset.bind + '.')
            )
            .sort((a, b) => b.dataset.bind.length - a.dataset.bind.length)[0];
    }
    function jumpToIssue(issue) {
        if (!Object.hasOwn(tabs, issue.tab)) return;
        tab = issue.tab;
        if (tab === 'offers') {
            const index = config.offers.findIndex((offer) => offer.id === issue.offer_id);
            selected = index >= 0 ? index : Number(issue.path.split('.')[1]);
        }
        render();
        const input = issueControl(issue);
        if (!input) return;
        window.offerweave_OfferWorkspace.open(input);
        openSettings(input);
        for (let parent = input.parentElement; parent; parent = parent.parentElement)
            if (parent.tagName === 'DETAILS') parent.open = true;
        input.focus({ preventScroll: true });
        input.scrollIntoView({ block: 'center', behavior: 'auto' });
    }
    function paintValidation() {
        const box = root.querySelector('.qb-message');
        if (!box) return;
        root.querySelectorAll('[data-validation-message], [data-offer-error]').forEach((node) =>
            node.remove()
        );
        root.querySelectorAll('[data-validation-marked]').forEach((input) => {
            input.removeAttribute('aria-invalid');
            const ids = (input.getAttribute('aria-describedby') || '')
                .split(' ')
                .filter((id) => !id.startsWith('offerweave-field-error-'));
            if (ids.length) input.setAttribute('aria-describedby', ids.join(' '));
            else input.removeAttribute('aria-describedby');
            delete input.dataset.validationMarked;
        });
        box.classList.toggle('qb-error', error || validationIssues.length > 0);
        box.setAttribute('role', error || validationIssues.length ? 'alert' : 'status');
        if (!validationIssues.length) {
            box.textContent = message;
            return;
        }
        box.innerHTML =
            '<strong>' +
            esc(
                __('Please check the following fields. Your changes are still in the editor.', 'offerweave')
            ) +
            '</strong><ul class="qb-validation-list">' +
            validationIssues
                .map(
                    (issue, index) =>
                        '<li><div><strong>' +
                        esc(issue.location) +
                        '</strong><span>' +
                        esc(issue.message) +
                        '</span></div><button type="button" class="qb-button qb-secondary" data-jump-issue="' +
                        index +
                        '">' +
                        esc(__('Go to field', 'offerweave')) +
                        '</button></li>'
                )
                .join('') +
            '</ul>';
        box.querySelectorAll('[data-jump-issue]').forEach((button) =>
            button.addEventListener('click', () =>
                jumpToIssue(validationIssues[Number(button.dataset.jumpIssue)])
            )
        );
        const flagged = new Set();
        validationIssues.forEach((issue, index) => {
            const input = issueControl(issue);
            if (input && !input.hasAttribute('data-validation-marked')) {
                const id = 'offerweave-field-error-' + index;
                const detail = document.createElement('small');
                detail.id = id;
                detail.className = 'qb-field-error';
                detail.dataset.validationMessage = '';
                detail.textContent = issue.message;
                input.after(detail);
                input.dataset.validationMarked = '';
                input.setAttribute('aria-invalid', 'true');
                input.setAttribute(
                    'aria-describedby',
                    ((input.getAttribute('aria-describedby') || '') + ' ' + id).trim()
                );
            }
            if (issue.tab === 'offers')
                flagged.add(issue.offer_id || config.offers[Number(issue.path.split('.')[1])]?.id);
        });
        root.querySelectorAll('[data-offer-index]').forEach((button) => {
            if (!flagged.has(config.offers[Number(button.dataset.offerIndex)]?.id)) return;
            const badge = document.createElement('small');
            badge.className = 'qb-field-error';
            badge.dataset.offerError = '';
            badge.textContent = __('Check fields', 'offerweave');
            button.append(badge);
        });
    }
    function updateTextCounters() {
        root.querySelectorAll('input[data-bind], textarea[data-bind]').forEach((input) => {
            const parts = input.dataset.bind.split('.');
            const key = parts[0] === 'settings' ? parts[1] : parts[2];
            const limit = boot.textLimits?.[parts[0]]?.[key];
            const fact = parts[0] === 'offers' && key === 'facts' && parts.length === 4;
            if (!limit || (!fact && parts[0] !== 'settings' && parts.length !== 3)) return;
            let counter = input.parentElement.querySelector('[data-text-counter]');
            if (!counter) {
                counter = document.createElement('small');
                counter.dataset.textCounter = '';
                counter.className = 'qb-text-counter';
                input.after(counter);
            }
            const lines = input.dataset.valueType === 'lines';
            const length = lines
                ? Math.max(0, ...input.value.split('\n').map((line) => [...line.trim()].length))
                : [...input.value].length;
            counter.textContent = sprintf(
                lines
                    ? /* translators: 1: character count of the longest line, 2: character limit per line. */
                      __('Longest line: %1$d / %2$d characters', 'offerweave')
                    : /* translators: 1: character count, 2: character limit. */
                      __('%1$d / %2$d characters', 'offerweave'),
                length,
                limit
            );
            counter.classList.toggle('qb-over-limit', length > limit);
        });
    }
