    function factEvents() {
        root.querySelectorAll('[data-fact-row]').forEach((row) => {
            const i = Number(row.dataset.factRow),
                p = 'offers.' + selected + '.fact_icons.' + i;
            window.offerweave_Images.bindIcon(
                row.querySelector('.qb-fact-icon-control'),
                () => config.offers[selected].fact_icons[i],
                (image) => set(p, image)
            );
        });
        const change = (order, focusIndex) => {
            const o = config.offers[selected],
                p = 'offers.' + selected;
            const facts = o.facts,
                icons = o.fact_icons;
            const prefix = 'offer:' + o.id + ':fact:';
            for (const dictionary of Object.values(config.languages?.translations || {})) {
                const old = { ...dictionary };
                for (const key of Object.keys(dictionary)) if (key.startsWith(prefix)) delete dictionary[key];
                order.forEach((source, index) => {
                    if (source !== null && Object.hasOwn(old, prefix + source))
                        dictionary[prefix + index] = old[prefix + source];
                });
            }
            set(
                p + '.facts',
                order.map((i) => (i === null ? '' : facts[i]))
            );
            set(
                p + '.fact_icons',
                order.map((i) =>
                    i === null
                        ? window.offerweave_Images.emptyIcon()
                        : icons[i] || window.offerweave_Images.emptyIcon()
                )
            );
            render();
            (
                root.querySelector('[data-bind="' + p + '.facts.' + focusIndex + '"]') ||
                root.querySelector('[data-fact-add]')
            )?.focus();
        };
        root.querySelector('[data-fact-add]')?.addEventListener('click', () => {
            const o = config.offers[selected];
            if (o.facts.length < 4) change([...o.facts.map((_, i) => i), null], o.facts.length);
        });
        root.querySelectorAll('[data-fact-action]').forEach((button) =>
            button.addEventListener('click', () => {
                const o = config.offers[selected],
                    i = Number(button.dataset.factIndex),
                    action = button.dataset.factAction;
                const order = o.facts.map((_, index) => index);
                let target = i;
                if (action === 'remove') {
                    order.splice(i, 1);
                    target = Math.min(i, order.length - 1);
                } else {
                    target = i + (action === 'up' ? -1 : 1);
                    if (target < 0 || target >= order.length) return;
                    [order[i], order[target]] = [order[target], order[i]];
                }
                change(order, target);
            })
        );
    }
    /* PRO_SURCHARGES_END */
    function offerEvents() {
        factEvents();
        const imageIndex = selected;
        window.offerweave_Images.bind(
            root.querySelector('.qb-offer-image-editor'),
            () => config.offers[imageIndex].image,
            (image) => set('offers.' + imageIndex + '.image', image)
        );
        for (const [button, output, shortcode] of [
            ['[data-copy-shortcode]', '[data-offer-shortcode]', 'offerweave_offer'],
            ['[data-copy-add-shortcode]', '[data-add-shortcode]', 'offerweave_add'],
        ])
            root.querySelector(button)?.addEventListener('click', async (e) => {
                const code = '[' + shortcode + ' id="' + config.offers[selected].id + '"]';
                try {
                    await navigator.clipboard.writeText(code);
                    e.target.textContent = __('Copied', 'offerweave');
                } catch {
                    const range = document.createRange();
                    range.selectNodeContents(root.querySelector(output));
                    const selection = window.getSelection();
                    selection.removeAllRanges();
                    selection.addRange(range);
                    e.target.textContent = __('Selected – please copy', 'offerweave');
                }
            });
        root.querySelectorAll('[data-offer-index]').forEach((b) =>
            b.addEventListener('click', () => {
                selected = Number(b.dataset.offerIndex);
                render();
            })
        );
        root.querySelector('[data-add-offer]')?.addEventListener('click', () => {
            const o = clone(defaults.offer);
            o.id = unique('angebot', config.offers);
            config.offers.push(o);
            selected = config.offers.length - 1;
            dirty = true;
            render();
        });
        root.querySelector('[data-duplicate-offer]')?.addEventListener('click', () => {
            const o = clone(config.offers[selected]);
            o.id = unique(o.id, config.offers);
            o.name += ' ' + __('– Copy', 'offerweave');
            config.offers.push(o);
            selected = config.offers.length - 1;
            dirty = true;
            render();
        });
        root.querySelector('[data-delete-offer]')?.addEventListener('click', async () => {
            const target = config.offers[selected];
            const parents = config.offers.filter(
                (o) => o.component_ids?.includes(target.id) || Object.hasOwn(o.component_prices || {}, target.id) || o.selection_parent === target.id
            );
            parents.push(...(config.promotions || []).filter(p => p.offer_ids?.includes(target.id)).map(p => ({name: p.name || p.id})));
            if (parents.length) {
                message =
                    __('This offer is used in:', 'offerweave') +
                    ' ' +
                    parents.map((o) => o.name).join(', ') +
                    __('. Please remove the assignment there first.', 'offerweave');
                error = true;
                render();
                return;
            }
            if (
                await offerweave_Dialogs.confirm(
                    __(
                        'Remove this offer from the configuration? Previously saved requests will be preserved.',
                        'offerweave'
                    ),
                    {
                        title: __('Remove offer', 'offerweave'),
                        confirmLabel: __('Remove offer', 'offerweave'),
                        danger: true,
                    }
                )
            ) {
                const removed = config.offers[selected].id;
                config.offers.splice(selected, 1);
                config.selection_rules.offer_ids = config.selection_rules.offer_ids.filter(
                    (id) => id !== removed
                );
                if (config.selection_rules.scope === 'offers' && !config.selection_rules.offer_ids.length)
                    config.selection_rules.enabled = false;
                for (const [old, id] of Object.entries(config.legacy_item_map || {}))
                    if (id === removed) delete config.legacy_item_map[old];
                dirty = true;
                render();
            }
        });
        /* PRO_GROUP_EVENTS_END */
    }
