    function fieldEvents() {
        root.querySelector('[data-add-field]').addEventListener('click', () => {
            config.fields.push({
                id: unique('feld', config.fields),
                label: __('New field', 'offerweave'),
                type: 'text',
                required: false,
                enabled: true,
                placeholder: '',
                options: [],
            });
            selected = config.fields.length - 1;
            dirty = true;
            render();
        });
        root.querySelectorAll('[data-delete-field]').forEach((b) =>
            b.addEventListener('click', async () => {
                if (
                    await offerweave_Dialogs.confirm(
                        __(
                            'Remove this form field? Old requests will retain their original details.',
                            'offerweave'
                        ),
                        {
                            title: __('Remove form field', 'offerweave'),
                            confirmLabel: __('Remove form field', 'offerweave'),
                            danger: true,
                        }
                    )
                ) {
                    config.fields.splice(Number(b.dataset.deleteField), 1);
                    dirty = true;
                    render();
                }
            })
        );
        root.querySelectorAll('[data-field-move]').forEach((b) =>
            b.addEventListener('click', () => {
                const [i, d] = b.dataset.fieldMove.split(':').map(Number),
                    j = i + d;
                [config.fields[i], config.fields[j]] = [config.fields[j], config.fields[i]];
                selected = j;
                dirty = true;
                render();
            })
        );
    }
