    function mountSettings(main) {
        // Move the existing panels without changing their controls or data bindings.
        const groups = [
            [
                'general',
                __('General and labels', 'offerweave'),
                ['settings.brand', 'settings.quantity_label'],
            ],
            [
                'prices',
                __('Prices and conditions', 'offerweave'),
                ['settings.currency', 'tax.enabled', 'selection_rules.enabled'],
            ],
            ['documents', __('Documents', 'offerweave'), ['legal.document_type']],
            ['provider', __('Provider', 'offerweave'), ['legal.audience']],
            ['requests', __('Requests and privacy', 'offerweave'), ['settings.notification_email']],
            [
                'security',
                __('Protection and data', 'offerweave'),
                ['settings.captcha_provider', 'settings.retention_days'],
            ],
        ];
        const nav = document.createElement('nav');
        nav.className = 'qb-offer-sections qb-settings-sections';
        nav.setAttribute('aria-label', __('Settings sections', 'offerweave'));
        const workspace = document.createElement('div');
        workspace.className = 'qb-settings-workspace';
        workspace.append(nav);
        for (const [key, label, paths] of groups) {
            const area = document.createElement('div');
            area.dataset.settingsArea = key;
            area.id = 'offerweave-settings-area-' + key;
            nav.insertAdjacentHTML(
                'beforeend',
                '<button type="button" data-settings-area-button="' +
                    key +
                    '" aria-controls="' +
                    area.id +
                    '">' +
                    esc(label) +
                    '</button>'
            );
            for (const path of paths) {
                const panel = main.querySelector('[data-bind="' + path + '"]')?.closest('.qb-panel');
                if (panel) area.append(panel);
            }
            workspace.append(area);
        }
        main.prepend(workspace);
        nav.addEventListener('click', (event) => {
            const button = event.target.closest('[data-settings-area-button]');
            if (!button) return;
            settingsArea = button.dataset.settingsAreaButton;
            showSettings();
        });
        showSettings();
    }
